const $ = (q, root = document) => root.querySelector(q);
const $$ = (q, root = document) => [...root.querySelectorAll(q)];
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const norm = s => String(s || '').normalize('NFD').replace(/\p{M}/gu, '').toLowerCase().replace(/ς/g,'σ');
const compact = s => norm(s).replace(/[^\p{L}\p{N}]/gu,'');
const readStore = (k, fallback) => {try{const value=JSON.parse(localStorage.getItem('presocratic.'+k));if(value==null)return fallback;if(Array.isArray(fallback))return Array.isArray(value)?value:fallback;if(fallback&&typeof fallback==='object')return value&&typeof value==='object'&&!Array.isArray(value)?value:fallback;return value}catch{return fallback}};
const writeStore = (k, v) => {try{localStorage.setItem('presocratic.'+k,JSON.stringify(v))}catch{}};
