 $('#search-status').textContent=(result.valid?counts.join(' · '):'Enter a word, a name, or a DK reference.')+(state.originalsUnavailable&&$('#search-scope').value!=='reading'?' · Diels 1922 could not load; results cover the reading collection only.':'');
