document.addEventListener('change',e=>{const comparison=e.target.closest('[data-comparison-side]');if(comparison&&state.comparison){state.comparison[comparison.dataset.comparisonSide]=comparison.value;renderComparison(comparison.dataset.comparisonSide);return}const select=e.target.closest('[data-translation-select]');if(select)chooseTranslation(select.dataset.translationSelect,select.value,{focus:true})});
$('#global-search').addEventListener('input',e=>{clearTimeout(state.searchTimer);if(!e.isComposing)state.searchTimer=setTimeout(()=>renderSearch(e.target.value),100)});
$('#global-search').addEventListener('keydown',e=>{if(e.isComposing)return;if(e.key==='Enter'){e.preventDefault();renderSearch(e.target.value);$('#search-results a.result, #search-results .no-results a')?.click()}else if(e.key==='ArrowDown'){e.preventDefault();renderSearch(e.target.value);$('#search-results a.result, #search-results .no-results a')?.focus()}});
$('#search-scope').addEventListener('change',()=>renderSearch($('#global-search').value));
$('#search-dialog').addEventListener('close',()=>clearTimeout(state.searchTimer));
document.addEventListener('keydown',e=>{const typing=/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)||e.target.isContentEditable;if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openSearch();return}if(e.key==='Escape'){$('.reader-tools-menu[open]')?.removeAttribute('open');$('#contents-dialog')?.close();return}if(e.metaKey||e.ctrlKey||e.altKey||e.isComposing||typing||$('dialog[open]'))return;if(e.key==='/'){e.preventDefault();openSearch()}if(state.currentAuthor&&['j','k'].includes(e.key.toLowerCase())){e.preventDefault();stepFragment(e.key.toLowerCase()==='j'?1:-1)}});
document.addEventListener('click',e=>{if(!e.target.closest('.reader-tools-menu'))$('.reader-tools-menu[open]')?.removeAttribute('open')});

$$('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));
window.addEventListener('hashchange',handleRoute);
window.addEventListener('popstate',handleRoute);
window.addEventListener('beforeprint',preparePrint);
window.addEventListener('afterprint',finishPrint);
async function init(){try{const [cat,corpus,original,coverage,artworks]=await Promise.all([fetch('/data/catalogue.json').then(r=>{if(!r.ok)throw Error('Catalogue unavailable');return r.json()}),fetch('/data/corpus.json').then(r=>{if(!r.ok)throw Error('Texts unavailable');return r.json()}),fetch('/data/originals.json').then(r=>{if(!r.ok)throw Error('Diels 1922 unavailable');return r.json()}).then(data=>{if(!Array.isArray(data.fragments))throw Error('Diels 1922 incomplete');return data}).catch(()=>({fragments:[],unavailable:true})),fetch('/data/coverage.json').then(r=>r.ok?r.json():null).catch(()=>null),fetch('/data/artworks.json').then(r=>r.ok?r.json():{artworks:[]}).catch(()=>({artworks:[]}))]);state.artworks=artworks.artworks;state.coverage=coverage;state.authors=cat.entries;state.fragments=corpus.fragments.filter(f=>!f.aliasOf);state.originals=original.fragments||[];state.originalsUnavailable=original.unavailable===true;state.all=[...state.fragments,...state.originals];for(const f of state.all){state.byId.set(f.id,f);for(const alias of f.aliases||[])state.byId.set(alias,f);const map=f.originalEdition?state.originalByChapter:state.byChapter;if(!map.has(f.chapter))map.set(f.chapter,[]);map.get(f.chapter).push(f)}for(const fs of state.byChapter.values())fs.sort((a,b)=>String(a.number).localeCompare(String(b.number),undefined,{numeric:true}));state.ready=true;applyPreferences();handleRoute();if($('#search-dialog').open)renderSearch($('#global-search').value)}catch(e){state.loadError=true;if($('#search-dialog').open)renderSearch($('#global-search').value);toast('Reading controls could not load. The page text remains available; reload to try again.');console.error(e)}}
init();
